<script setup>
import {ref,onActivated} from 'vue'
import {http} from '../api/http'
const rows=ref([]),busy=ref(false),page=ref(1),total=ref(0),detail=ref(null)
const statuses={not_started:'待开始',in_progress:'制作中',pending_qc:'待质检',completed:'已完成'}
async function load(){busy.value=true;try{const r=await http.get('/employee/tasks',{params:{page:page.value,page_size:10}});rows.value=r.data;total.value=r.total}catch{}finally{busy.value=false}}
onActivated(load)
</script>
<template><div class="page-title"><div><h1>我的任务</h1><p>仅展示本人负责或参与的制琴任务，可查看进度与质检历史。</p></div><el-button @click="load">刷新</el-button></div><el-card shadow="never"><el-table v-loading="busy" :data="rows" empty-text="暂无参与的任务"><el-table-column prop="task_code" label="任务编号"/><el-table-column prop="name" label="任务名称"/><el-table-column prop="guitar_model" label="吉他型号"/><el-table-column prop="owner_name" label="负责人"/><el-table-column label="进度"><template #default="{row}">{{row.completed_quantity}} / {{row.planned_quantity}}</template></el-table-column><el-table-column label="状态"><template #default="{row}">{{statuses[row.status]}}</template></el-table-column><el-table-column prop="due_date" label="预计完成"/><el-table-column label="操作"><template #default="{row}"><el-button link type="primary" @click="detail=row">详情</el-button></template></el-table-column></el-table><el-pagination class="pagination" v-model:current-page="page" :total="total" :page-size="10" layout="total,prev,pager,next" @current-change="load"/></el-card><WorkspaceDialog :model-value="!!detail" title="任务详情（只读）" @close="detail=null"><template v-if="detail"><p>{{detail.name}} · {{detail.guitar_model}}</p><p>{{detail.start_date}} 至 {{detail.due_date}}</p><p>{{detail.notes||'无备注'}}</p><el-table :data="detail.inspections" empty-text="尚无质检记录"><el-table-column label="结果"><template #default="{row}">{{row.result==='passed'?'通过':'不通过'}}</template></el-table-column><el-table-column prop="notes" label="质检备注"/><el-table-column prop="inspected_at" label="质检时间（UTC）"/></el-table></template></WorkspaceDialog></template>
